using Microsoft.AspNetCore.Authorization;using Microsoft.AspNetCore.Mvc;
public sealed record AgentRequest(string Prompt,int MaxToolCalls=3,int MaxTokens=2000);
[ApiController,Route("api/v1/agent"),Authorize]public sealed class AgentController(AgentHarness harness):ControllerBase{[HttpPost("run")]public async Task<ActionResult<AgentResult>>Run(AgentRequest request,CancellationToken ct)=>Ok(await harness.RunAsync(request.Prompt,request.MaxToolCalls,request.MaxTokens,ct));}